import { ZodDefaultDef } from 'zod';
import { JsonSchema7Type, parseDef } from 'openai/src/_vendor/zod-to-json-schema/parseDef';
import { Refs } from 'openai/src/_vendor/zod-to-json-schema/Refs';

export function parseDefaultDef(_def: ZodDefaultDef, refs: Refs): JsonSchema7Type & { default: any } {
  return {
    ...parseDef(_def.innerType._def, refs),
    default: _def.defaultValue(),
  };
}
